-- Constellation 1: Yazılım Geliştirme · "Kod Avcısı"
-- Ids: lesson n -> questions n*10+k -> options (n*10+k)*10+p

                     difficulty, duration_min, xp_reward, star_x, star_y, sort_order) VALUES
(1, 'python-ile-ilk-adim', 1, $$Python ile İlk Adım$$,
 $$Değişkenler, veri tipleri, koşullar ve döngülerle ilk Python programlarını yaz.$$,
 ARRAY[$$Değişken ve temel veri tiplerini kullanmak$$, $$if/else ile karar yapıları kurmak$$,
       $$for ve while döngüleriyle tekrar eden işleri otomatikleştirmek$$, $$Fonksiyon tanımlayıp yeniden kullanmak$$],
 ARRAY[$$Python, okunabilir sözdizimi sayesinde programlamaya başlamak için en sevilen dillerden biridir. Web geliştirmeden veri bilimine, otomasyondan yapay zekaya kadar pek çok alanda kullanılır.$$,
       $$Bir değişken, bir değere verdiğin isimdir: yas = 21 dediğinde yas artık 21'i temsil eder. Python türleri kendisi çıkarır; int, float, str ve bool en sık kullanacağın temel tiplerdir.$$,
       $$Karar yapıları (if, elif, else) programının farklı durumlara göre davranmasını sağlar. Döngüler (for, while) aynı işi tekrar tekrar yazmadan yapmanı sağlar. Tekrar eden mantığı def ile bir fonksiyona taşımak kodunu sade ve test edilebilir kılar.$$],
 'kqtD5dpn9C8', 'BEGINNER', 30, 100, 120, 220, 1),
(2, 'veri-yapilari-ve-algoritmalar', 1, $$Veri Yapıları ve Algoritmalar$$,
 $$Doğru veri yapısını seçmeyi ve algoritmaları Big-O ile karşılaştırmayı öğren.$$,
 ARRAY[$$Dizi, yığın (stack), kuyruk (queue) ve hash tablosunu ayırt etmek$$, $$Big-O gösterimiyle zaman karmaşıklığını yorumlamak$$,
       $$İkili arama (binary search) mantığını kavramak$$, $$Probleme uygun veri yapısını seçmek$$],
 ARRAY[$$Veri yapısı, verini bellekte nasıl düzenlediğindir; algoritma ise o veri üzerinde izlediğin adımlardır. Doğru eşleşme, aynı problemi saniyeler yerine milisaniyelerde çözmeni sağlar.$$,
       $$Yığın (stack) son giren ilk çıkar (LIFO) mantığıyla çalışır; geri al (undo) özelliği buna güzel bir örnektir. Kuyruk (queue) ilk giren ilk çıkar (FIFO) prensibiyle çalışır. Hash tablosu ise anahtardan değere ortalama O(1) erişim sağlar.$$,
       $$Big-O gösterimi, girdi büyüdükçe algoritmanın nasıl ölçeklendiğini anlatır. Sıralı bir dizide ikili arama her adımda arama alanını yarıya indirir ve O(log n) sürede sonuca ulaşır; doğrusal arama ise O(n) sürer.$$],
 '8hly31xKli0', 'INTERMEDIATE', 45, 150, 240, 130, 2),
(3, 'git-ile-takim-calismasi', 1, $$Git ile Takım Çalışması$$,
 $$Commit, branch, merge ve pull request akışıyla ekibinle aynı kod üzerinde çakışmadan çalış.$$,
 ARRAY[$$Commit ile değişiklikleri anlamlı adımlara bölmek$$, $$Branch açıp özellik geliştirmek$$,
       $$Merge sırasında çakışma (conflict) çözmek$$, $$Pull request ile kod incelemesi yapmak$$],
 ARRAY[$$Git, kodunun zaman makinesidir. Her commit projenin o anki fotoğrafını ve bir açıklamasını saklar; böylece neyin, ne zaman ve neden değiştiğini her zaman görebilirsin.$$,
       $$Branch'ler ana koddan bağımsız çalışma alanlarıdır. Yeni bir özelliği kendi branch'inde geliştirir, bitince ana branch'e merge edersin. Aynı satırı iki kişi farklı değiştirdiyse Git bir çakışma bildirir ve hangisinin kalacağına sen karar verirsin.$$,
       $$Takım çalışmasında pull request (PR) altın standarttır: Değişikliğini ekibe sunar, kod incelemesinden geçirir, sonra birleştirirsin. Code Night gibi yoğun bir gecede bile düzenli commit ve PR alışkanlığı ekibi hızlandırır.$$],
 'RGOj5yH7evk', 'BEGINNER', 25, 100, 250, 290, 3),
(4, 'rest-api-tasarimi', 1, $$REST API Tasarımı$$,
 $$Kaynak odaklı URL'ler, doğru HTTP metotları ve durum kodlarıyla tutarlı API'ler tasarla.$$,
 ARRAY[$$Kaynakları isim odaklı URL'lerle modellemek$$, $$GET, POST, PUT, PATCH ve DELETE'i doğru kullanmak$$,
       $$Anlamlı HTTP durum kodları döndürmek$$, $$Hata cevaplarını standart bir formatta vermek$$],
 ARRAY[$$REST, istemci ile sunucunun HTTP üzerinden kaynaklar aracılığıyla konuştuğu bir mimari stildir. İyi bir API'de URL'ler fiil değil isim içerir: /lessons/42/attempts gibi.$$,
       $$HTTP metotları niyeti anlatır: GET okur, POST yeni kaynak oluşturur, PUT tamamen değiştirir, PATCH kısmen günceller, DELETE siler. GET isteklerinin yan etkisiz, PUT ve DELETE'in ise idempotent olması beklenir.$$,
       $$Durum kodları istemcinin ne olduğunu anlamasını sağlar: 200 başarılı, 201 oluşturuldu, 400 hatalı istek, 401 kimlik doğrulama gerekli, 403 yetkisiz, 404 bulunamadı, 409 çakışma. Hata gövdelerini RFC 9457 Problem Details gibi bir standartla vermek API'yi öngörülebilir kılar.$$],
 'GZvSYJDk-us', 'INTERMEDIATE', 40, 150, 370, 210, 4),
(5, 'temiz-kod-ve-solid', 1, $$Temiz Kod ve SOLID$$,
 $$SOLID prensipleri ve temiz kod alışkanlıklarıyla büyüdükçe bozulmayan yazılımlar kur.$$,
 ARRAY[$$Tek Sorumluluk Prensibi ile sınıfları sadeleştirmek$$, $$Açık/Kapalı Prensibi ile genişletilebilir tasarım yapmak$$,
       $$Bağımlılıkları tersine çevirerek modülleri ayırmak$$, $$Anlamlı isimler ve küçük fonksiyonlarla okunabilir kod yazmak$$],
 ARRAY[$$Temiz kod, başkasının (ve altı ay sonraki senin) kolayca okuyup değiştirebildiği koddur. Anlamlı isimler, kısa fonksiyonlar ve tek bir işi iyi yapan sınıflar bu yolun temelidir.$$,
       $$SOLID beş prensipten oluşur: Single Responsibility (tek bir değişme nedeni), Open/Closed (değiştirmeden genişletmek), Liskov Substitution (alt tipler üst tipin yerine geçebilmeli), Interface Segregation (küçük, odaklı arayüzler) ve Dependency Inversion (soyutlamalara bağımlı olmak).$$,
       $$Bu projede rozet kuralları Strategy deseniyle yazıldı: Yeni bir rozet eklemek için mevcut kodu değiştirmeden yeni bir kural sınıfı eklemek yeterli. İşte Open/Closed Prensibi'nin gerçek hayattaki karşılığı.$$],
 'pTB0EiLXUC8', 'ADVANCED', 45, 200, 430, 95, 5);



