INSERT INTO questions (id, lesson_id, position, prompt, explanation) VALUES
(11, 1, 1, $$Python'da bir fonksiyon tanımlamak için hangi anahtar kelime kullanılır?$$, $$Python'da fonksiyonlar def anahtar kelimesiyle tanımlanır: def selamla(): ...$$),
(12, 1, 2, $$print(2 ** 3) ifadesinin çıktısı nedir?$$, $$** üs alma operatörüdür; 2'nin 3. kuvveti 8'dir.$$),
(13, 1, 3, $$Aşağıdakilerden hangisi Python'da bir liste oluşturur?$$, $$Köşeli parantez liste oluşturur; normal parantez demet (tuple), süslü parantez küme (set) oluşturur.$$),
(14, 1, 4, $$for i in range(3): print(i) kodu hangi değerleri yazdırır?$$, $$range(3) 0'dan başlar ve 3'e kadar (3 hariç) sayar: 0, 1, 2.$$),
(21, 2, 1, $$Son giren elemanın ilk çıktığı (LIFO) veri yapısı hangisidir?$$, $$Yığın LIFO çalışır; tarayıcıdaki geri tuşu ve geri al işlemleri yığın mantığına dayanır.$$),
(22, 2, 2, $$Sıralı bir dizide ikili aramanın zaman karmaşıklığı nedir?$$, $$İkili arama her adımda arama alanını yarıya indirdiği için O(log n) sürede çalışır.$$),
(23, 2, 3, $$Anahtar-değer çiftlerine ortalama O(1) erişim sağlayan yapı hangisidir?$$, $$Hash tablosu anahtarı bir hash fonksiyonuyla doğrudan bir konuma eşler; ortalama erişim O(1)'dir.$$),
(24, 2, 4, $$İç içe iki döngüyle n elemanlı listenin tüm ikililerini karşılaştıran algoritmanın karmaşıklığı nedir?$$, $$Her eleman için tüm elemanları dolaşmak n × n işlem demektir: O(n²).$$),
(31, 3, 1, $$Hazırlanan değişiklikleri depo geçmişine kaydeden Git komutu hangisidir?$$, $$git commit değişiklikleri açıklamasıyla geçmişe kaydeder; git push ise uzak depoya gönderir.$$),
(32, 3, 2, $$Ana koddan bağımsız olarak yeni bir özellik geliştirmek için ne kullanılır?$$, $$Branch, ana koddan ayrılan bağımsız bir geliştirme hattıdır.$$),
(33, 3, 3, $$İki kişi aynı satırı farklı şekilde değiştirip merge ettiğinde ne olur?$$, $$Git hangi değişikliğin doğru olduğunu bilemez; çakışmayı bildirir ve çözümü geliştiriciye bırakır.$$),
(34, 3, 4, $$Pull request'in temel amacı nedir?$$, $$PR, değişikliklerin ekip tarafından incelenip onaylandıktan sonra ana koda birleştirilmesini sağlar.$$),
(41, 4, 1, $$Yeni bir kaynak oluşturmak için en uygun HTTP metodu hangisidir?$$, $$POST yeni bir kaynak oluşturur; başarılı olursa genellikle 201 Created döner.$$),
(42, 4, 2, $$Kimlik doğrulaması yapılmamış bir istek için hangi durum kodu döndürülmelidir?$$, $$401 kimliğin doğrulanmadığını, 403 ise kimlik bilinse de yetkinin olmadığını anlatır.$$),
(43, 4, 3, $$Aşağıdaki URL'lerden hangisi REST prensiplerine en uygundur?$$, $$REST'te URL kaynağı adlandırır; işlemi HTTP metodu belirler: GET /lessons.$$),
(44, 4, 4, $$Aynı isteği birden çok kez göndermek sonucu değiştirmiyorsa bu işlem nasıl adlandırılır?$$, $$İdempotent işlemler tekrarlansa da aynı sonucu üretir; PUT ve DELETE buna örnektir.$$),
(51, 5, 1, $$Bir sınıfın değişmek için yalnızca tek bir nedeni olması gerektiğini söyleyen prensip hangisidir?$$, $$Single Responsibility Prensibi, her sınıfın tek bir sorumluluğu olmasını önerir.$$),
(52, 5, 2, $$Yeni davranış eklerken mevcut kodu değiştirmek yerine genişletmeyi öneren prensip hangisidir?$$, $$Open/Closed: Yazılım genişlemeye açık, değişikliğe kapalı olmalıdır.$$),
(53, 5, 3, $$Üst seviye modüllerin detaylara değil soyutlamalara bağımlı olmasını söyleyen prensip hangisidir?$$, $$Dependency Inversion, modüllerin arayüzler gibi soyutlamalar üzerinden konuşmasını önerir.$$),
(54, 5, 4, $$Aşağıdakilerden hangisi temiz kod pratiği değildir?$$, $$Kodu kopyalamak bakımı zorlaştırır; DRY prensibi tekrarı ortak bir yere taşımayı önerir.$$);
